import { describe, expect, it } from 'vitest';
import { MetadataSearchDto } from 'src/dtos/search.dto';
import { UpdateAssetDto } from 'src/dtos/asset.dto';
import { ExifResponseSchema } from 'src/dtos/exif.dto';

describe('rating probe', () => {
  it('update accepts -1', () => {
    expect(UpdateAssetDto.schema.safeParse({ rating: -1 }).success).toBe(true);
  });
  it('update rejects 0', () => {
    expect(UpdateAssetDto.schema.safeParse({ rating: 0 }).success).toBe(false);
  });
  it('search rating -1', () => {
    const r = MetadataSearchDto.schema.safeParse({ rating: -1 });
    console.log('SEARCH -1 =>', r.success ? 'ACCEPTED' : 'REJECTED: ' + JSON.stringify(r.error.issues.map(i => i.message)));
    expect(true).toBe(true);
  });
  it('exif response -1', () => {
    const r = ExifResponseSchema.safeParse({ rating: -1 });
    console.log('EXIF RESP -1 =>', r.success ? 'ACCEPTED' : 'REJECTED: ' + JSON.stringify(r.error.issues.map(i => i.message)));
    expect(true).toBe(true);
  });
});
EOF
cd $R/server && timeout 300 pnpm exec vitest run --config test/vitest.config.mjs ../server/probe-tmp.spec.ts 2>&1 | grep -v "tsconfig-paths\|Experimental" | tail -30
